 *   price: number,
 *   image_url?: string,
 *   tags?: string[],
 *   is_available?: boolean,
 *   total_sold?: number
 * }} row - Raw row returned by the most_loved_products view.
 *
 * @returns {{
 *   id: string,
 *   name: string,
 *   description: string,
 *   price: number,
 *   image_url: string | null,
 *   tags: string[],
 *   is_available: boolean
 * }}
 */
// TODO(dev2): confirm whether the live view exposes `product_name` or `name`
// — the SQL migration uses `p.name` but the shared types spec says `product_name`.
// If the column is `name`, swap `row.product_name` → `row.name` here.
export function normaliseProduct(row) {
  // Guard: surface a clear error in dev if a required field is missing
  if (process.env.NODE_ENV !== 'production') {
    if (!row.product_id) console.warn('normaliseProduct: missing product_id', row);
    if (!row.product_name) console.warn('normaliseProduct: missing product_name', row);
    if (row.price === undefined || row.price === null)
      console.warn('normaliseProduct: missing price', row);
  }

  return {
    // Rename database PKs / verbose column names to short UI-friendly keys
    id: row.product_id ?? '',
    name: row.product_name ?? '',

    // Optional fields — use agreed defaults so consumers never receive undefined
    description: row.description ?? '',
    price: row.price ?? 0,
    image_url: row.image_url ?? null,
    // Ensure tags is always an array even if the DB returns null
    tags: Array.isArray(row.tags) ? row.tags : [],
    // Default to true so a missing flag doesn't hide products unexpectedly
    is_available: row.is_available ?? true,
  };
}
