import { supabase } from '../lib/supabaseClient';
import { normaliseProduct } from '../lib/products';
import ProductCard from './ProductCard';

/**
 * Fetches the top-3 most-loved products from Supabase and renders
 * them as a responsive grid of <ProductCard /> components.
 */
export default function MostLoved() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    let cancelled = false;

    async function fetchMostLoved() {
      setLoading(true);
      setError(null);

      const { data, error: sbError } = await supabase
        .from('most_loved_products')
        .select('*');

      if (cancelled) return;

      if (sbError) {
        setError(sbError.message);
        setLoading(false);
        return;
      }

      // Normalise every row through the shared helper — no inline remapping here
      setProducts((data ?? []).map(normaliseProduct));
      setLoading(false);
    }

    fetchMostLoved();

    // Prevent state updates if the component unmounts before the fetch resolves
    return () => { cancelled = true; };
  }, []);

  if (loading) {
    return (
      <section aria-busy="true" className="py-12 text-center text-gray-500">
        Loading most loved products…
      </section>
    );
  }

  if (error) {
    return (
      <section className="py-12 text-center text-red-600">
        <p>Failed to load products: {error}</p>
      </section>
    );
  }

  if (products.length === 0) {
    return (
      <section className="py-12 text-center text-gray-400">
        <p>No products to show yet.</p>
      </section>
    );
  }

  return (
    <section className="py-12 px-4">
      <h2 className="text-2xl font-bold text-center mb-8">Most Loved</h2>
      <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3 max-w-5xl mx-auto">
        {products.map((product) => (
          <ProductCard key={product.id} product={product} />
        ))}
      </div>
    </section>
  );
}
