 * Displays a single product in a card layout.
 */

/**
 * ProductCard
 *
 * Renders a product tile with image, name, description, price and tags.
 * Unavailable products are visually dimmed and the CTA is disabled.
 *
 * @param {{ product: ProductShape }} props
 *
 * @typedef {{
 *   id: string,          // Unique product identifier (UUID)
 *   name: string,        // Display name of the product
 *   description: string, // Short marketing copy (may be empty string)
 *   price: number,       // Unit price in the store's base currency (e.g. 9.99)
 *   image_url: string | null, // Absolute URL to the hero image, or null for placeholder
 *   tags: string[],      // Array of label strings, e.g. ['vegan', 'gluten-free']
 *   is_available: boolean // False → product is out of stock / hidden from purchase
 * }} ProductShape
 */
export default function ProductCard({ product }) {
  const {
    id,
    name,
    description,
    price,
    image_url,
    tags,
    is_available,
  } = product;

  return (
    <article
      key={id}
      className={`rounded-2xl shadow-md overflow-hidden flex flex-col bg-white
        ${ !is_available ? 'opacity-50' : '' }`}
    >
      {/* Product image — fall back to a neutral placeholder when image_url is null */}
      <div className="h-48 bg-gray-100 overflow-hidden">
        {image_url ? (
          <img
            src={image_url}
            alt={name}
            className="w-full h-full object-cover"
            loading="lazy"
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center text-gray-300 text-sm">
            No image
          </div>
        )}
      </div>

      <div className="p-4 flex flex-col flex-1 gap-2">
        <h3 className="text-lg font-semibold text-gray-800">{name}</h3>

        {description && (
          <p className="text-sm text-gray-500 flex-1">{description}</p>
        )}

        {/* Render tags as small pill badges */}
        {tags.length > 0 && (
          <ul className="flex flex-wrap gap-1" aria-label="Product tags">
            {tags.map((tag) => (
              <li
                key={tag}
                className="px-2 py-0.5 text-xs rounded-full bg-indigo-50 text-indigo-600"
              >
                {tag}
              </li>
            ))}
          </ul>
        )}

        <div className="flex items-center justify-between mt-2">
          <span className="text-base font-bold text-gray-900">
            £{price.toFixed(2)}
          </span>

          <button
            disabled={!is_available}
            // TODO(dev2): wire up to cart / Stripe checkout flow
            className="px-4 py-1.5 text-sm rounded-xl bg-indigo-600 text-white
              hover:bg-indigo-700 disabled:cursor-not-allowed disabled:bg-gray-300
              transition-colors"
          >
            {is_available ? 'Add to cart' : 'Unavailable'}
          </button>
        </div>
      </div>
    </article>
  );
}
